      "Подготовьте фарш (Фарш говяжий): достаньте его из холодильника непосредственно перед готовкой, разомните крупные комки и заранее отмерьте добавки и специи. Если по рецепту нужно формовать котлеты или фрикадельки, держите массу прохладной до самого формирования.",
      "Для гарнира подготовьте Картофель: нарежьте одинаковыми кусочками и начинайте варить или запекать в момент, указанный в рецепте, чтобы гарнир был готов вместе с основным блюдом. Отмерьте компоненты соуса: Молоко и Сливочное масло. Перемешайте их до однородности, если рецепт требует общей заправки, и отложите до нужного этапа.",
